import { ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, Input, OnInit, Output } from '@angular/core';
import { bundleDetailRes } from '../../../interfaces/myfile.interface';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { FormsModule } from '@angular/forms';
import { DocumentTab } from '../../../../userpanel/interfaces/individual.interface';
import { DoccardComponent } from '../../doccard/doccard.component';
import { IconComponent } from '../../icon/icon.component';
import { ButtonComponent } from '../../button/button.component';
import { IndividualService } from '../../../../userpanel/services/individual/individual.service';
import { SourceCardComponent } from '../../source-card/source-card.component';
import { highlightModeType } from '../../../../pdf/interfaces/pdf.interface';

@Component({
  selector: 'selected-docs',
  changeDetection: ChangeDetectionStrategy.OnPush,
  standalone: true,
  imports: [FormsModule, MatCheckboxModule, DoccardComponent, IconComponent, ButtonComponent, SourceCardComponent],
  templateUrl: './selected-docs.component.html',
  styleUrl: './selected-docs.component.scss'
})
export class SelectedDocsComponent implements OnInit {
  @Input() viewlist: any[] = [];
  @Output() close = new EventEmitter<void>();
  @Output() OnSave = new EventEmitter<any>();
  @Input() isLink: highlightModeType;
  isSaving: boolean = false;
  isAllChecked: boolean = true;
  isSelected: boolean = true;
  constructor(private readonly individualService: IndividualService, private cdr: ChangeDetectorRef) {

  }

  ngOnInit(): void {
    
    this.viewlist.map((item) => item.isChecked = true);
  }

  onClose() {
    this.close.emit();
  }

  checkAll() {
    this.isAllChecked = !this.isAllChecked;
    this.viewlist.map((item) => {
      item.isChecked = this.isAllChecked;
      console.log(`Item ${item.nBundledetailid} checked status: ${item.isChecked}`);
    });
    this.checkSelected();
    this.cdr.detectChanges();
  }

  cardevent(event: any) {
    if (event.type === 'C') {
      this.OnSelect();
    }
  }

  OnSelect() {
    let ind: number = this.viewlist.findIndex(a => !a.isChecked);
    if (ind > -1) {
      this.isAllChecked = false;
    } else {
      this.isAllChecked = true;
    }
    this.checkSelected();
  }

  checkSelected() {
    if (this.viewlist.filter(a => a.isChecked).length > 0) {
      this.isSelected = true;
    } else {
      this.isSelected = false;
    }
  }

  async OnSubmit() {
    
    try {
      const selectedFiles: string[] = this.viewlist.filter(a => a.isChecked).map((item) => item.nBundledetailid);
      if (!selectedFiles.length) return;


      if (this.isLink) {
        this.OnSave.emit(this.viewlist.filter(a => a.isChecked));
        return;
      }

      if (this.isSaving) return;
      this.isSaving = true;
      const files: DocumentTab[] = await this.individualService.getTabinfo(selectedFiles);

      if (!files.length) {
        return;
      }

      this.isSaving = false;
      this.OnSave.emit(files);
    } catch (error) {
    }
  }
}